'use strict';
const fs=require('fs'),path=require('path'),crypto=require('crypto'),assert=require('assert');
const {pathToFileURL}=require('url');
const root=process.cwd(),out=path.join(root,'.cvf/runtime/cvf-expense-touch-local-review-20261010');
const web=path.join(root,'EXTENSIONS/CVF_v1.6_AGENT_PLATFORM/cvf-web');
const source=path.join(web,'src/expenses/ExpenseList.tsx');
const digest=()=>crypto.createHash('sha256').update(fs.readFileSync(source)).digest('hex');
const start=digest();
const rgb=s=>s.match(/[\d.]+/g).slice(0,3).map(Number);
const luminance=s=>rgb(s).map(x=>x/255).map(x=>x<=0.04045?x/12.92:((x+0.055)/1.055)**2.4).reduce((sum,x,i)=>sum+x*[0.2126,0.7152,0.0722][i],0);
const contrast=(a,b)=>(Math.max(luminance(a),luminance(b))+0.05)/(Math.min(luminance(a),luminance(b))+0.05);
(async()=>{
 fs.mkdirSync(out,{recursive:true});
 const entry=path.join(out,'review-entry.tsx');
 const spec=path.relative(out,source).replace(/\\/g,'/');
 fs.writeFileSync(entry,`import React from 'react';import {createRoot} from 'react-dom/client';import {ExpenseList} from ${JSON.stringify(spec)};createRoot(document.getElementById('root')).render(React.createElement(ExpenseList,{expenses:[{id:'LOCAL-MARCH',date:'2026-03-31',label:'Independent row',amount:12000},{id:'LOCAL-OTHER',date:'2027-03-01',label:'Another year',amount:14000}]}));`);
 const vite=await import(pathToFileURL(path.join(web,'node_modules/vite/dist/node/index.js')).href);
 const build=await vite.build({configFile:false,envFile:false,root:out,logLevel:'silent',mode:'production',define:{'process.env.NODE_ENV':'"production"'},resolve:{alias:[{find:'react-dom',replacement:path.join(web,'node_modules/react-dom').replace(/\\/g,'/')},{find:'react',replacement:path.join(web,'node_modules/react').replace(/\\/g,'/')}]},oxc:{jsx:{runtime:'automatic'}},build:{write:false,minify:true,sourcemap:false,emptyOutDir:false,lib:{entry,formats:['iife'],name:'IndependentExpense'}}});
 const chunks=(Array.isArray(build)?build:[build]).flatMap(x=>x.output);assert.equal(chunks.length,1);
 const code=chunks[0].code.replace(/<\/script/gi,'<\\/script');
 const html=path.join(out,'independent-320.html');
 fs.writeFileSync(html,`<!doctype html><meta charset="utf-8"><style>:root{color-scheme:dark;--cvf-bg-page:#111218;--cvf-surface:#1c1d27;--cvf-text-primary:#f4f7fb;--cvf-text-secondary:#a3adc2;--cvf-text-muted:#6f7890;--cvf-border:rgba(255,255,255,.08);--cvf-border-strong:rgba(255,255,255,.14);--cvf-warning:#f59e0b;--cvf-accent:#5b5cf6}body{margin:0;background:var(--cvf-bg-page);font-family:system-ui}main{padding:16px}td:first-child{white-space:nowrap}:focus-visible{outline:2px solid var(--cvf-accent);outline-offset:2px}</style><main id="root"></main><script>${code}</script>`);
 const {chromium}=require(path.join(web,'node_modules/@playwright/test'));const browser=await chromium.launch({headless:true});let report;
 try {
  const ctx=await browser.newContext({viewport:{width:320,height:844}});const page=await ctx.newPage();page.setDefaultTimeout(15000);
  const external=[],errors=[];await ctx.route('**/*',r=>r.request().url().startsWith('file:')?r.continue():r.abort());
  page.on('request',r=>{if(!r.url().startsWith('file:'))external.push(r.url())});page.on('pageerror',e=>errors.push(e.message));page.on('console',m=>{if(m.type()==='error')errors.push(m.text())});
  await page.goto(pathToFileURL(html).href);await page.waitForSelector('[data-expense-id="LOCAL-MARCH"]');
  await page.locator('input[type=month]').fill('2026-03');await page.waitForFunction(()=>document.querySelectorAll('[data-expense-id]').length===1);
  const measure=()=>page.evaluate(()=>{const input=document.querySelector('input'),section=document.querySelector('section'),note=document.querySelector('[role=note]'),tds=[...document.querySelectorAll('tbody td')];const rect=el=>{const r=el.getBoundingClientRect();return {height:r.height,width:r.width,left:r.left,right:r.right}};return {input:rect(input),note:rect(note),table:rect(document.querySelector('table')),overflow:document.documentElement.scrollWidth-innerWidth,clipped:section.scrollWidth>section.clientWidth,surface:getComputedStyle(section).backgroundColor,noticeColor:getComputedStyle(note).color,rowColors:tds.map(td=>getComputedStyle(td).color),ids:[...document.querySelectorAll('[data-expense-id]')].map(el=>el.dataset.expenseId)}});
  const actual=await measure();fs.writeFileSync(path.join(out,'measurement-diagnostic.json'),JSON.stringify(actual,null,2));assert.deepEqual(actual.ids,['LOCAL-MARCH']);assert(actual.input.height>=44&&actual.input.width>=44);assert.equal(actual.overflow,0);
  for(const b of [actual.input,actual.note,actual.table])assert(b.left>=0&&b.right<=320);
  const rowContrast=Math.min(...actual.rowColors.map(x=>contrast(x,actual.surface))),noticeContrast=contrast(actual.noticeColor,actual.surface);assert(rowContrast>=4.5&&noticeContrast>=4.5);
  await page.evaluate(()=>{document.querySelector('input').style.height='36px'});const negative=await measure();assert.equal(negative.input.height,36);let rejected=false;try{assert(negative.input.height>=44)}catch(e){assert.equal(e.name,'AssertionError');rejected=true}assert(rejected);
  await page.evaluate(()=>{document.querySelector('input').style.height='44px'});assert.equal((await measure()).input.height,44);
  assert.equal(external.length,0);assert.equal(errors.length,0);assert.equal(digest(),start);
  report={status:'PASS',viewport:{width:320,height:844},sourceSha256:start,actual,rowContrast,noticeContrast,negative:{control:'DOM-only height override; no source mutation',height:negative.input.height,threshold:44,rejectedByAssertion:rejected},restoredHeight:44,externalRequests:external.length,pageErrors:errors.length,oracle:'Reviewer own fixture and literal 44/4.5; worker test not imported',browserVersion:browser.version()};
  await page.screenshot({path:path.join(out,'independent-320.png'),fullPage:true});await ctx.close();
 }finally{await browser.close()}
 fs.writeFileSync(path.join(out,'probe-results.json'),JSON.stringify(report,null,2)+'\n');process.stdout.write(JSON.stringify(report)+'\n');
})().catch(e=>{process.stderr.write(e.stack+'\n');process.exitCode=1});
